const svg = document.getElementById("se-pkt");
const out = document.getElementById("se-pkt-read");
const tIn = document.getElementById("se-t");
const tLab = document.getElementById("se-t-val");
const W = 640, H = 280, padL = 60, padR = 30, padT = 20, padB = 40;
const xMin = -8, xMax = 8;
function xPx(x){ return padL + (x-xMin)/(xMax-xMin)*(W-padL-padR); }
function yPx(p){ return H - padB - p*(H-padT-padB)/0.5; }
function clear(){ while(svg.firstChild) svg.removeChild(svg.firstChild); }
function axes(){
  svg.appendChild(SVG("line",{x1:padL,y1:H-padB,x2:W-padR,y2:H-padB,stroke:"var(--line)"}));
  svg.appendChild(SVG("line",{x1:padL,y1:padT,x2:padL,y2:H-padB,stroke:"var(--line)"}));
  for(let xv=-8;xv<=8;xv+=2){
    const x = xPx(xv);
    svg.appendChild(SVG("line",{x1:x,y1:H-padB,x2:x,y2:H-padB+4,stroke:"var(--line)"}));
    const t = SVG("text",{x,y:H-padB+18,"text-anchor":"middle","font-size":11,fill:"var(--mute)"});
    t.textContent = xv; svg.appendChild(t);
  }
  const xl = SVG("text",{x:W-padR,y:H-padB-6,"text-anchor":"end","font-size":12,fill:"var(--mute)"});
  xl.textContent = "x"; svg.appendChild(xl);
  const yl = SVG("text",{x:padL+6,y:padT+10,"font-size":12,fill:"var(--mute)"});
  yl.textContent = "|ψ(x,t)|²"; svg.appendChild(yl);
}
function draw(t){
  clear(); axes();
  // free Gaussian: |psi|^2 = (1/sqrt(pi*sigma_t^2)) exp(-x^2/sigma_t^2), sigma_t^2 = 1 + t^2/16
  const sigma2 = 1 + (t*t)/16;
  const sigma = Math.sqrt(sigma2);
  const norm = 1/Math.sqrt(Math.PI*sigma2);
  let pts = [];
  let total = 0;
  const dx = 16/200;
  for(let i=0;i<=200;i++){
    const x = xMin + i*dx;
    const p = norm * Math.exp(-x*x/sigma2);
    pts.push([xPx(x), yPx(p)]);
    total += p*dx;
  }
  const path = SVG("path",{
    d: "M"+pts.map(p=>p.join(" ")).join(" L"),
    fill:"none", stroke:"var(--cyan)", "stroke-width":2.2
  });
  svg.appendChild(path);
  // shaded fill under curve
  const fill = SVG("path",{
    d: "M"+pts.map(p=>p.join(" ")).join(" L")+` L${xPx(xMax)} ${yPx(0)} L${xPx(xMin)} ${yPx(0)} Z`,
    fill:"var(--cyan)", opacity:0.12
  });
  svg.appendChild(fill);
  out.textContent = `t = ${t.toFixed(1)}    width σ(t) = √(1 + t²/16) = ${sigma.toFixed(3)}    ∫|ψ|² dx ≈ ${total.toFixed(4)}`;
}
function update(){
  const t = parseFloat(tIn.value);
  tLab.textContent = "t = "+t.toFixed(1);
  draw(t);
}
tIn.addEventListener("input", update);
update();

const svg = document.getElementById("se-well");
const out = document.getElementById("se-well-read");
const kIn = document.getElementById("se-well-k");
const kLab = document.getElementById("se-well-k-val");
const tIn = document.getElementById("se-well-t");
const tLab = document.getElementById("se-well-t-val");
const btn = document.getElementById("se-well-play");
const W = 640, H = 280, padL = 50, padR = 30, padT = 20, padB = 40;
const L = Math.PI, sigma = 0.45, x0 = L/2;
const Nmodes = 40, Nx = 240;
// Eigenstates phi_n(x) = sqrt(2/L) sin(n x); energies E_n = n^2 (units hbar=2m=1).
// Initial Gaussian psi0 ~ exp(-(x-x0)^2/(2 sigma^2)) exp(i k0 x), normalized over [0,L].
function computeCoeffs(k0){
  const dx = L / Nx;
  const psiR = new Array(Nx+1), psiI = new Array(Nx+1);
  let normSq = 0;
  for(let i=0;i<=Nx;i++){
    const x = i*dx;
    const env = Math.exp(-((x-x0)*(x-x0))/(2*sigma*sigma));
    psiR[i] = env*Math.cos(k0*x);
    psiI[i] = env*Math.sin(k0*x);
    normSq += (psiR[i]*psiR[i] + psiI[i]*psiI[i]) * dx;
  }
  const norm = 1/Math.sqrt(normSq);
  for(let i=0;i<=Nx;i++){ psiR[i]*=norm; psiI[i]*=norm; }
  const A = Math.sqrt(2/L);
  const cR = new Array(Nmodes+1), cI = new Array(Nmodes+1);
  for(let n=1;n<=Nmodes;n++){
    let sR = 0, sI = 0;
    for(let i=0;i<=Nx;i++){
      const x = i*dx;
      const phin = A*Math.sin(n*x);
      sR += phin*psiR[i]*dx;
      sI += phin*psiI[i]*dx;
    }
    cR[n] = sR; cI[n] = sI;
  }
  return {cR, cI};
}
let k0 = parseFloat(kIn.value);
let coeffs = computeCoeffs(k0);
function xPx(x){ return padL + (x/L)*(W-padL-padR); }
function yPx(p, scale){ return H - padB - p*(H-padT-padB)/scale; }
function clear(){ while(svg.firstChild) svg.removeChild(svg.firstChild); }
function axes(){
  svg.appendChild(SVG("rect",{x:0,y:padT,width:padL,height:H-padT-padB,fill:"var(--violet)",opacity:0.10}));
  svg.appendChild(SVG("rect",{x:W-padR,y:padT,width:padR,height:H-padT-padB,fill:"var(--violet)",opacity:0.10}));
  svg.appendChild(SVG("line",{x1:padL,y1:H-padB,x2:W-padR,y2:H-padB,stroke:"var(--line)"}));
  svg.appendChild(SVG("line",{x1:padL,y1:padT,x2:padL,y2:H-padB,stroke:"var(--violet)","stroke-width":2}));
  svg.appendChild(SVG("line",{x1:W-padR,y1:padT,x2:W-padR,y2:H-padB,stroke:"var(--violet)","stroke-width":2}));
  [0, L/4, L/2, 3*L/4, L].forEach((xv,i)=>{
    const x = xPx(xv);
    svg.appendChild(SVG("line",{x1:x,y1:H-padB,x2:x,y2:H-padB+4,stroke:"var(--line)"}));
    const t = SVG("text",{x,y:H-padB+18,"text-anchor":"middle","font-size":11,fill:"var(--mute)"});
    t.textContent = ["0","π/4","π/2","3π/4","π"][i];
    svg.appendChild(t);
  });
  const xl = SVG("text",{x:W-padR,y:H-padB-6,"text-anchor":"end","font-size":12,fill:"var(--mute)"});
  xl.textContent = "x"; svg.appendChild(xl);
  const yl = SVG("text",{x:padL+6,y:padT+12,"font-size":12,fill:"var(--mute)"});
  yl.textContent = "|ψ(x,t)|²"; svg.appendChild(yl);
}
function draw(t){
  clear(); axes();
  const A = Math.sqrt(2/L);
  let pts = [];
  let total = 0;
  let pmax = 0;
  const xs = new Array(Nx+1), p2 = new Array(Nx+1);
  const dx = L/Nx;
  for(let i=0;i<=Nx;i++){
    const x = i*dx;
    let pr = 0, pi = 0;
    for(let n=1;n<=Nmodes;n++){
      const a = n*n*t;
      const ca = Math.cos(a), sa = Math.sin(a);
      const phin = A*Math.sin(n*x);
      // (cR + i cI)(cos a - i sin a) = (cR cos a + cI sin a) + i(cI cos a - cR sin a)
      pr += (coeffs.cR[n]*ca + coeffs.cI[n]*sa) * phin;
      pi += (coeffs.cI[n]*ca - coeffs.cR[n]*sa) * phin;
    }
    const p = pr*pr + pi*pi;
    xs[i] = x; p2[i] = p;
    total += p*dx;
    if(p>pmax) pmax = p;
  }
  const scale = Math.max(pmax, 1.5);
  for(let i=0;i<=Nx;i++){ pts.push([xPx(xs[i]), yPx(p2[i], scale)]); }
  svg.appendChild(SVG("path",{
    d: "M"+pts.map(p=>p.join(" ")).join(" L"),
    fill:"none", stroke:"var(--cyan)", "stroke-width":2.2
  }));
  svg.appendChild(SVG("path",{
    d: "M"+pts.map(p=>p.join(" ")).join(" L")+` L${xPx(L)} ${yPx(0,scale)} L${xPx(0)} ${yPx(0,scale)} Z`,
    fill:"var(--cyan)", opacity:0.12
  }));
  out.textContent = `t = ${t.toFixed(3)}    ∫|ψ|² dx ≈ ${total.toFixed(4)}    revival period T_rev = 2π ≈ 6.283`;
}
function update(){
  const t = parseFloat(tIn.value);
  tLab.textContent = "t = " + t.toFixed(3);
  draw(t);
}
let raf = null;
function stepAnim(){
  let t = parseFloat(tIn.value);
  t += 0.025;
  if(t > parseFloat(tIn.max)) t = parseFloat(tIn.min);
  tIn.value = t;
  update();
  raf = requestAnimationFrame(stepAnim);
}
kIn.addEventListener("input", ()=>{
  k0 = parseFloat(kIn.value);
  kLab.textContent = "k₀ = " + k0.toFixed(1);
  coeffs = computeCoeffs(k0);
  update();
});
tIn.addEventListener("input", update);
btn.addEventListener("click", ()=>{
  if(raf){ cancelAnimationFrame(raf); raf = null; btn.textContent = "Play"; btn.classList.remove("active"); }
  else { btn.textContent = "Pause"; btn.classList.add("active"); stepAnim(); }
});
update();

const svg = document.getElementById("se-stat");
const out = document.getElementById("se-stat-read");
const mixIn = document.getElementById("se-mix");
const mixLab = document.getElementById("se-mix-val");
const btn = document.getElementById("se-anim");
const W = 640, H = 260, padL = 50, padR = 30, padT = 20, padB = 30;
const xMin = 0, xMax = Math.PI;
let t = 0, animId = null;
// infinite-well eigenstates on [0,π]: phi_n(x) = sqrt(2/π) sin(n x), E_n = n^2 (in units)
function xPx(x){ return padL + (x-xMin)/(xMax-xMin)*(W-padL-padR); }
function yPx(p, scale=1.0){ return H/2 - p*(H-padT-padB)/(2*scale); }
function clear(){ while(svg.firstChild) svg.removeChild(svg.firstChild); }
function axes(){
  svg.appendChild(SVG("line",{x1:padL,y1:H/2,x2:W-padR,y2:H/2,stroke:"var(--line)"}));
  svg.appendChild(SVG("line",{x1:padL,y1:padT,x2:padL,y2:H-padB,stroke:"var(--line)"}));
  const xl = SVG("text",{x:W-padR,y:H/2-6,"text-anchor":"end","font-size":12,fill:"var(--mute)"});
  xl.textContent = "x ∈ [0, π]"; svg.appendChild(xl);
  const yl = SVG("text",{x:padL+6,y:padT+10,"font-size":12,fill:"var(--mute)"});
  yl.textContent = "|ψ(x,t)|²  (cyan) and Re ψ (yellow)"; svg.appendChild(yl);
}
function draw(){
  clear(); axes();
  const a2 = parseFloat(mixIn.value);
  const a1 = Math.sqrt(1-a2);
  const a2s = Math.sqrt(a2);
  const E1 = 1, E2 = 4;
  let ptsP = [], ptsR = [];
  const N = 200;
  for(let i=0;i<=N;i++){
    const x = xMin + (i/N)*(xMax-xMin);
    const phi1 = Math.sqrt(2/Math.PI)*Math.sin(x);
    const phi2 = Math.sqrt(2/Math.PI)*Math.sin(2*x);
    // psi = a1 e^{-iE1 t} phi1 + a2s e^{-iE2 t} phi2
    const cr = a1*Math.cos(-E1*t)*phi1 + a2s*Math.cos(-E2*t)*phi2;
    const ci = a1*Math.sin(-E1*t)*phi1 + a2s*Math.sin(-E2*t)*phi2;
    const p2 = cr*cr + ci*ci;
    ptsP.push([xPx(x), yPx(p2, 1.5)]);
    ptsR.push([xPx(x), yPx(cr, 1.5)]);
  }
  svg.appendChild(SVG("path",{d:"M"+ptsR.map(p=>p.join(" ")).join(" L"),fill:"none",stroke:"var(--yellow)","stroke-width":1.5,opacity:0.7}));
  svg.appendChild(SVG("path",{d:"M"+ptsP.map(p=>p.join(" ")).join(" L"),fill:"none",stroke:"var(--cyan)","stroke-width":2.4}));
  const beatPeriod = 2*Math.PI/Math.abs(E2-E1);
  out.textContent = `|c₁|² = ${(1-a2).toFixed(2)}, |c₂|² = ${a2.toFixed(2)} | E₁=1, E₂=4 | beat period = 2π/|E₂-E₁| ≈ ${beatPeriod.toFixed(3)} | t = ${t.toFixed(2)}`;
}
function step(){
  t += 0.04;
  draw();
  animId = requestAnimationFrame(step);
}
mixIn.addEventListener("input", ()=>{
  mixLab.textContent = "|c₂|² = "+parseFloat(mixIn.value).toFixed(2);
  draw();
});
btn.addEventListener("click", ()=>{
  if(animId){ cancelAnimationFrame(animId); animId = null; btn.textContent = "Animate"; btn.classList.remove("active"); }
  else { btn.textContent = "Pause"; btn.classList.add("active"); step(); }
});
draw();

const svg = document.getElementById("se-ladder");
const out = document.getElementById("se-ladder-read");
const W = 640, H = 320;
const leftW = 280, midW = W - leftW;
const padT = 20, padB = 30;
const Nlvl = 6;
let selected = 2;
function clear(){ while(svg.firstChild) svg.removeChild(svg.firstChild); }
// Hermite polynomial H_n(x) by recursion
function hermite(n, x){
  if(n===0) return 1;
  if(n===1) return 2*x;
  let h0 = 1, h1 = 2*x;
  for(let k=1;k<n;k++){
    const h2 = 2*x*h1 - 2*k*h0;
    h0 = h1; h1 = h2;
  }
  return h1;
}
function factorial(n){ let f=1; for(let i=2;i<=n;i++) f*=i; return f; }
function psi(n, x){
  // unnormalized for plotting: H_n(x) * e^{-x^2/2}
  return hermite(n, x) * Math.exp(-x*x/2);
}
function draw(){
  clear();
  // potential parabola V = x^2/2 (in units hbar=omega=m=1)
  // y maps energy: 0 at bottom, E_max at top
  const Emax = Nlvl + 1;
  function eY(E){ return H - padB - (E/Emax)*(H-padT-padB); }
  function xPxL(x){ return 30 + (x+4)/8 * (leftW-50); }
  // V(x) curve
  let vp = [];
  for(let i=0;i<=80;i++){
    const x = -4 + 8*i/80;
    const V = 0.5*x*x;
    vp.push([xPxL(x), eY(V)]);
  }
  svg.appendChild(SVG("path",{d:"M"+vp.map(p=>p.join(" ")).join(" L"),fill:"none",stroke:"var(--mute)","stroke-width":1.5,"stroke-dasharray":"4 3"}));
  // levels
  for(let n=0;n<Nlvl;n++){
    const E = n + 0.5;
    const y = eY(E);
    const turning = Math.sqrt(2*E);
    const x0 = xPxL(-turning), x1 = xPxL(turning);
    const color = (n===selected) ? "var(--yellow)" : "var(--cyan)";
    const line = SVG("line",{x1:x0,y1:y,x2:x1,y2:y,stroke:color,"stroke-width":(n===selected?3:2)});
    line.style.cursor = "pointer";
    line.dataset.n = n;
    line.addEventListener("click", e=>{ selected = parseInt(e.target.dataset.n); draw(); });
    svg.appendChild(line);
    // label E_n
    const lab = SVG("text",{x:x1+8,y:y+4,"font-size":12,fill:color});
    lab.textContent = `E${n} = ${(n+0.5).toFixed(1)} ℏω`;
    svg.appendChild(lab);
    // invisible wide hit area for clicks
    const hit = SVG("rect",{x:x0,y:y-8,width:x1-x0,height:16,fill:"transparent"});
    hit.style.cursor = "pointer";
    hit.dataset.n = n;
    hit.addEventListener("click", e=>{ selected = parseInt(e.target.dataset.n); draw(); });
    svg.appendChild(hit);
  }
  // labels
  const tt = SVG("text",{x:30,y:padT+12,"font-size":12,fill:"var(--mute)"});
  tt.textContent = "V(x) = ½x²"; svg.appendChild(tt);
  // Right panel: wavefunction of selected
  const padR = 30, axisX0 = leftW + 30, axisX1 = W - padR;
  const cyW = axisX1 - axisX0;
  const cyMid = H/2;
  function xPxR(x){ return axisX0 + (x+4)/8 * cyW; }
  svg.appendChild(SVG("line",{x1:axisX0,y1:cyMid,x2:axisX1,y2:cyMid,stroke:"var(--line)"}));
  svg.appendChild(SVG("line",{x1:axisX0,y1:padT,x2:axisX0,y2:H-padB,stroke:"var(--line)"}));
  // Hermite × Gaussian, normalized to fit panel
  let pts = [];
  let maxAbs = 0;
  for(let i=0;i<=200;i++){
    const x = -4 + 8*i/200;
    const v = psi(selected, x);
    if(Math.abs(v) > maxAbs) maxAbs = Math.abs(v);
    pts.push([x, v]);
  }
  const ampScale = (H/2 - padT - 10)/maxAbs;
  const path = SVG("path",{
    d: "M"+pts.map(([x,v])=>[xPxR(x), cyMid - v*ampScale].join(" ")).join(" L"),
    fill:"none", stroke:"var(--yellow)", "stroke-width":2
  });
  svg.appendChild(path);
  const ttl = SVG("text",{x:axisX0,y:padT+12,"font-size":12,fill:"var(--mute)"});
  ttl.textContent = `φ${selected}(x) = H${selected}(x) e^{-x²/2}`;
  svg.appendChild(ttl);
  // node count = n
  out.textContent = `Selected n = ${selected}: E${selected} = ${(selected+0.5).toFixed(2)} ℏω. Wavefunction has ${selected} node${selected===1?"":"s"} (zeros). Classical turning points at x = ±√(2E) = ±${Math.sqrt(2*(selected+0.5)).toFixed(3)}.`;
}
draw();

const svg = document.getElementById("se-hyd");
const out = document.getElementById("se-hyd-read");
const W = 640, H = 340, padT = 20, padB = 30;
let series = 1;
const E0 = 13.6;
function E(n){ return -E0/(n*n); }
function clear(){ while(svg.firstChild) svg.removeChild(svg.firstChild); }
function eY(e){
  // map energies in [-13.6, 0] to vertical pixels; -13.6 -> H-padB, 0 -> padT+10
  const yMax = H - padB - 30;
  const yMin = padT + 30;
  return yMin + (1 - (e + E0)/E0) * (yMax - yMin);
}
function draw(){
  clear();
  const xL = 80, xR = W - 60;
  // ionization line at E=0
  svg.appendChild(SVG("line",{x1:xL-10,y1:eY(0),x2:xR+10,y2:eY(0),stroke:"var(--mute)","stroke-dasharray":"4 3"}));
  const il = SVG("text",{x:xR+12,y:eY(0)+4,"font-size":12,fill:"var(--mute)"});
  il.textContent = "E = 0 (ionization)"; svg.appendChild(il);
  // levels n=1..6
  for(let n=1;n<=6;n++){
    const e = E(n);
    const y = eY(e);
    svg.appendChild(SVG("line",{x1:xL,y1:y,x2:xR,y2:y,stroke:"var(--cyan)","stroke-width":2,opacity:0.6}));
    const lab = SVG("text",{x:xL-8,y:y+4,"text-anchor":"end","font-size":12,fill:"var(--mute)"});
    lab.textContent = `n=${n}`; svg.appendChild(lab);
    const eLab = SVG("text",{x:xR+8,y:y+4,"font-size":11,fill:"var(--cyan)"});
    eLab.textContent = e.toFixed(2)+" eV"; svg.appendChild(eLab);
  }
  // transitions n=2..6 -> m=series
  const colors = {1:"var(--violet)", 2:"var(--yellow)", 3:"var(--pink)"};
  const color = colors[series];
  const m = series;
  let lines = [];
  for(let n=m+1;n<=6;n++){
    const x = xL + (n-m)*40 + 60;
    const yA = eY(E(n));
    const yB = eY(E(m));
    ensureArrow(svg, "hyd-arr-"+m, color);
    svg.appendChild(SVG("line",{x1:x,y1:yA,x2:x,y2:yB,stroke:color,"stroke-width":2,"marker-end":`url(#hyd-arr-${m})`}));
    const dE = Math.abs(E(n)-E(m));
    const wl = 1240/dE; // hc/E in nm with E in eV
    lines.push(`${n}→${m}: ΔE=${dE.toFixed(2)} eV, λ=${wl.toFixed(1)} nm`);
    const t = SVG("text",{x:x,y:yB+18,"text-anchor":"middle","font-size":10,fill:color});
    t.textContent = `${n}→${m}`;
    svg.appendChild(t);
  }
  out.textContent = lines.join("    ");
}
document.getElementById("hyd-lyman").addEventListener("click",()=>{series=1;setActive();draw();});
document.getElementById("hyd-balmer").addEventListener("click",()=>{series=2;setActive();draw();});
document.getElementById("hyd-paschen").addEventListener("click",()=>{series=3;setActive();draw();});
function setActive(){
  document.getElementById("hyd-lyman").classList.toggle("active", series===1);
  document.getElementById("hyd-balmer").classList.toggle("active", series===2);
  document.getElementById("hyd-paschen").classList.toggle("active", series===3);
}
draw();

const svg = document.getElementById("se-tun");
const out = document.getElementById("se-tun-read");
const Ein = document.getElementById("se-E"), Elab = document.getElementById("se-E-val");
const Ain = document.getElementById("se-a"), Alab = document.getElementById("se-a-val");
const W = 640, H = 280, padL = 50, padR = 40, padT = 20, padB = 50;
// schematic: V_0 = 1, hbar = 2m = 1
function clear(){ while(svg.firstChild) svg.removeChild(svg.firstChild); }
// exact T for rectangular barrier of height V_0, width a, particle mass m, energy E:
// E < V_0 :  T = 1 / (1 + (V0^2 / (4 E (V0-E))) * sinh^2(kappa a))
// E > V_0 :  T = 1 / (1 + (V0^2 / (4 E (E-V0))) * sin^2(k' a))
// E = V_0 :  T = 1 / (1 + (m V0 a^2)/(2 hbar^2))
function transT(EoverV0, a){
  const V0 = 1;
  const E = EoverV0 * V0;
  if(Math.abs(E-V0) < 1e-6){
    return 1/(1 + a*a/4); // hbar = 2m = 1 collapses pieces
  }
  if(E < V0){
    const kappa = Math.sqrt(V0 - E);
    const sh = Math.sinh(kappa*a);
    return 1/(1 + (V0*V0/(4*E*(V0-E)))*sh*sh);
  } else {
    const kp = Math.sqrt(E - V0);
    const sn = Math.sin(kp*a);
    return 1/(1 + (V0*V0/(4*E*(E-V0)))*sn*sn);
  }
}
function draw(){
  clear();
  const EoverV0 = parseFloat(Ein.value);
  const a = parseFloat(Ain.value);
  // potential profile axes
  const x0 = padL, x1 = W - padR;
  const y0 = padT, y1 = H - padB;
  // x-range -3..3, barrier from -a/2 to a/2
  const xMin = -3, xMax = 3;
  function xPx(x){ return x0 + (x-xMin)/(xMax-xMin)*(x1-x0); }
  function yPx(v){ return y1 - v*(y1-y0)/1.6; }
  // ground V=0 line
  svg.appendChild(SVG("line",{x1:x0,y1:yPx(0),x2:x1,y2:yPx(0),stroke:"var(--line)"}));
  // barrier
  svg.appendChild(SVG("rect",{x:xPx(-a/2),y:yPx(1),width:xPx(a/2)-xPx(-a/2),height:yPx(0)-yPx(1),fill:"var(--violet)",opacity:0.18,stroke:"var(--violet)","stroke-width":1.5}));
  const v0lab = SVG("text",{x:xPx(0),y:yPx(1)-6,"text-anchor":"middle","font-size":12,fill:"var(--violet)"});
  v0lab.textContent = "V₀"; svg.appendChild(v0lab);
  // energy line
  svg.appendChild(SVG("line",{x1:x0,y1:yPx(EoverV0),x2:x1,y2:yPx(EoverV0),stroke:"var(--yellow)","stroke-width":1.5,"stroke-dasharray":"5 3"}));
  const elab = SVG("text",{x:x0+6,y:yPx(EoverV0)-4,"font-size":12,fill:"var(--yellow)"});
  elab.textContent = "E"; svg.appendChild(elab);
  // wavefunction sketch
  const E = EoverV0;
  const kIn = Math.sqrt(E);
  let pts = [];
  const T = transT(EoverV0, a);
  const ampT = Math.sqrt(T);
  for(let i=0;i<=300;i++){
    const x = xMin + (i/300)*(xMax-xMin);
    let v = 0;
    if(x < -a/2){
      // incident + reflected: 1*cos(kx) (schematic, real part)
      const ampR = Math.sqrt(1-T);
      v = Math.cos(kIn*x*4) + ampR*Math.cos(-kIn*x*4 + Math.PI/3);
      v *= 0.18;
    } else if(x <= a/2){
      if(E < 1){
        // exponential decay through barrier
        const kappa = Math.sqrt(1-E);
        const start = Math.cos(kIn*(-a/2)*4) * 0.36;
        v = start * Math.exp(-kappa*4*(x+a/2));
        // continuity to right
      } else {
        const kp = Math.sqrt(E-1);
        v = 0.18 * Math.cos(kp*x*4);
      }
    } else {
      // transmitted
      v = ampT * 0.36 * Math.cos(kIn*x*4);
    }
    pts.push([xPx(x), yPx(EoverV0) - v*60]);
  }
  svg.appendChild(SVG("path",{d:"M"+pts.map(p=>p.join(" ")).join(" L"),fill:"none",stroke:"var(--cyan)","stroke-width":1.6}));
  // x axis ticks
  [-2,-1,0,1,2].forEach(xv=>{
    svg.appendChild(SVG("line",{x1:xPx(xv),y1:y1,x2:xPx(xv),y2:y1+4,stroke:"var(--line)"}));
    const t = SVG("text",{x:xPx(xv),y:y1+18,"text-anchor":"middle","font-size":11,fill:"var(--mute)"});
    t.textContent = xv; svg.appendChild(t);
  });
  out.textContent = `Transmission T(E,a) = ${T.toFixed(4)}, Reflection R = ${(1-T).toFixed(4)}, T+R = ${(T+(1-T)).toFixed(4)}` + (E<1 ? "  ← classically forbidden, yet T > 0 (tunneling)" : "  ← above barrier, oscillatory transmission resonances");
}
Ein.addEventListener("input", ()=>{ Elab.textContent = "E/V₀ = "+parseFloat(Ein.value).toFixed(2); draw(); });
Ain.addEventListener("input", ()=>{ Alab.textContent = "a = "+parseFloat(Ain.value).toFixed(1); draw(); });
draw();

const svg = document.getElementById("se-path");
const out = document.getElementById("se-path-read");
const hIn = document.getElementById("se-h"), hLab = document.getElementById("se-h-val");
const W = 640, H = 320, padL = 50, padR = 40, padT = 30, padB = 80;
// sample paths q_alpha(t) = alpha*t*(1-t) (fixed endpoints 0 at t=0, t=1)
// action S[alpha] = alpha^2/12 (for free particle action ½ ∫ q'² dt with the obvious analog)
// the stationary path is alpha = 0
const tMin = 0, tMax = 1;
const aMin = -3, aMax = 3;
function tx(t){ return padL + t*(W-padL-padR); }
function ty(q){ return H/2 - 60 - q*60; }
function clear(){ while(svg.firstChild) svg.removeChild(svg.firstChild); }
function action(alpha){
  // path q(t) = alpha*t*(1-t), q'(t) = alpha*(1-2t)
  // S = ∫_0^1 ½ q'^2 dt = ½ * alpha^2 * ∫(1-2t)^2 dt = ½ * alpha^2 * 1/3 = alpha^2/6
  return alpha*alpha/6;
}
function draw(){
  clear();
  const hbar = parseFloat(hIn.value);
  // top half: family of paths
  const N = 21;
  const ttl = SVG("text",{x:padL,y:padT-10,"font-size":12,fill:"var(--mute)"});
  ttl.textContent = "paths q(t) = α·t(1-t),  α ∈ [-3, 3]"; svg.appendChild(ttl);
  // axis
  svg.appendChild(SVG("line",{x1:tx(0),y1:ty(0),x2:tx(1),y2:ty(0),stroke:"var(--line)"}));
  for(let i=0;i<N;i++){
    const alpha = aMin + (i/(N-1))*(aMax-aMin);
    let pts = [];
    for(let j=0;j<=40;j++){
      const t = j/40;
      const q = alpha*t*(1-t);
      pts.push([tx(t), ty(q)]);
    }
    const isStat = Math.abs(alpha) < 0.18;
    const color = isStat ? "var(--yellow)" : "var(--cyan)";
    const opacity = isStat ? 1.0 : 0.35;
    svg.appendChild(SVG("path",{d:"M"+pts.map(p=>p.join(" ")).join(" L"),fill:"none",stroke:color,"stroke-width":isStat?2.4:1.2,opacity}));
  }
  // endpoints
  svg.appendChild(SVG("circle",{cx:tx(0),cy:ty(0),r:4,fill:"var(--ink)"}));
  svg.appendChild(SVG("circle",{cx:tx(1),cy:ty(0),r:4,fill:"var(--ink)"}));
  const en1 = SVG("text",{x:tx(0)-12,y:ty(0)+4,"font-size":11,fill:"var(--mute)","text-anchor":"end"}); en1.textContent="x_i"; svg.appendChild(en1);
  const en2 = SVG("text",{x:tx(1)+12,y:ty(0)+4,"font-size":11,fill:"var(--mute)"}); en2.textContent="x_f"; svg.appendChild(en2);
  // bottom half: cos(S/hbar) integrand vs alpha — visualizes oscillation
  const bx0 = padL, bx1 = W - padR, by0 = H - padB - 70, by1 = H - 12;
  const ttlB = SVG("text",{x:bx0,y:by0-4,"font-size":12,fill:"var(--mute)"});
  ttlB.textContent = `Re e^{i S(α)/ℏ} = cos(α²/(6ℏ)) — phase oscillation along family`; svg.appendChild(ttlB);
  svg.appendChild(SVG("line",{x1:bx0,y1:(by0+by1)/2,x2:bx1,y2:(by0+by1)/2,stroke:"var(--line)"}));
  let pts = [];
  const M = 600;
  for(let i=0;i<=M;i++){
    const alpha = aMin + (i/M)*(aMax-aMin);
    const phase = Math.cos(action(alpha)/hbar);
    const x = bx0 + (alpha-aMin)/(aMax-aMin)*(bx1-bx0);
    const y = (by0+by1)/2 - phase*((by1-by0)/2 - 6);
    pts.push([x,y]);
  }
  svg.appendChild(SVG("path",{d:"M"+pts.map(p=>p.join(" ")).join(" L"),fill:"none",stroke:"var(--pink)","stroke-width":1.6}));
  // alpha = 0 marker
  const x0 = bx0 + (0-aMin)/(aMax-aMin)*(bx1-bx0);
  svg.appendChild(SVG("line",{x1:x0,y1:by0,x2:x0,y2:by1,stroke:"var(--yellow)","stroke-width":1.5,"stroke-dasharray":"3 3"}));
  const xt = SVG("text",{x:x0,y:by1+12,"text-anchor":"middle","font-size":11,fill:"var(--yellow)"});
  xt.textContent = "α=0 (δS=0)"; svg.appendChild(xt);
  // axis labels
  [-3,-2,-1,0,1,2,3].forEach(a=>{
    const x = bx0 + (a-aMin)/(aMax-aMin)*(bx1-bx0);
    svg.appendChild(SVG("line",{x1:x,y1:by1,x2:x,y2:by1+3,stroke:"var(--line)"}));
    if(a!==0){
      const t = SVG("text",{x,y:by1+12,"text-anchor":"middle","font-size":10,fill:"var(--mute)"});
      t.textContent = a; svg.appendChild(t);
    }
  });
  // count oscillations as |alpha| ranges
  const oscAtEdge = Math.floor(action(aMax)/(hbar*Math.PI));
  out.textContent = `ℏ = ${hbar.toFixed(2)}. As ℏ→0 the phase wraps faster (≈ ${oscAtEdge} half-cycles between α=0 and α=3); off-stationary contributions cancel. The yellow path (α=0) survives — that's the classical solution.`;
}
hIn.addEventListener("input", ()=>{ hLab.textContent = "ℏ = "+parseFloat(hIn.value).toFixed(2); draw(); });
draw();
